import{_ as e,o as a,c as l,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"agent/Backend.md","filePath":"agent/Backend.md","lastUpdated":1789141852000}'),o={name:"agent/Backend.md"};function p(n,t,i,s,c,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<ol><li>先用 next.js 做一个全栈项目，学习一下 docker 、数据库这些打包、部署。反正我是这样学的</li><li>编程语言，数据库（ MySQL ），这两个学完先这个登录页面，写出来基本上就入门了。接着就是 redis nginx docker k8s 学完基本上算进阶了</li></ol><p>我是6年前端 我最近两个月在找工作 我工作前4年 用了Vue2/Vue3/uniapp 第五六年用了 React / nextjs</p><p>Agent</p><ol><li><p>台湾国立大学李宏毅的 2025 年<a href="./[https://www.youtube.com/playlist?list=PLJV_el3uVTsMMGi5kbnKP5DrDHZpTX0jT">最新课程</a>，被誉为中文](<a href="https://www.youtube.com/playlist?list=PLJV_el3uVTsMMGi5kbnKP5DrDHZpTX0jT%5C" target="_blank" rel="noreferrer">https://www.youtube.com/playlist?list=PLJV_el3uVTsMMGi5kbnKP5DrDHZpTX0jT\\</a>)%EF%BC%8C%E8%A2%AB%E8%AA%89%E4%B8%BA%E4%B8%AD%E6%96%87) AI 圈神课。</p></li><li><p>看完李宏毅的，可以看斯坦福的<a href="./[https://www.youtube.com/playlist?list=PLoROMvodv4rOY23Y0BoGoBGgQ1zmU_MT_">CS336</a>，从](<a href="https://www.youtube.com/playlist?list=PLoROMvodv4rOY23Y0BoGoBGgQ1zmU_MT_%5C" target="_blank" rel="noreferrer">https://www.youtube.com/playlist?list=PLoROMvodv4rOY23Y0BoGoBGgQ1zmU_MT_\\</a>)%EF%BC%8C%E4%BB%8E) 0 开始构建语言模型。</p></li><li><p>辅助的论文阅读，可以关注李沐的这个频道( <a href="https://www.youtube.com/playlist?list=PLFXJ6jwg0qW-7UM8iUTj3qKqdhbQULP5I)%EF%BC%8C%E4%BB%96%E7%9A%84%E5%88%86%E6%AE%B5%E7%B2%BE%E8%AF%BB" target="_blank" rel="noreferrer">https://www.youtube.com/playlist?list=PLFXJ6jwg0qW-7UM8iUTj3qKqdhbQULP5I)，他的分段精读</a> transformer ，我看了好多遍。</p></li><li><p>不喜欢理论只喜欢实践，也可以看看国内写的这个<a href="./[https://datawhalechina.github.io/hello-agents/#/](https://datawhalechina.github.io/hello-agents/#/)">hello-agents</a></p></li></ol><p>还有一些比较零碎的资料或者偏实践的，我在之前帖子里有写，就不放了。</p><p>总之，agent 开发，我作为从业者的看法是，已经从 2025 年初的探索阶段，过渡到成体系的标准应用了。至于你说的框架，额，怎么说呢？可能你们企业内用的多些，但是商业级的项目一般不会直接用框架。</p><p>基于 LLM 的 agent 开发，技术门槛主要是 开源开套件的熟练度吧，langchain 、langgraph 、dify 这些。</p><p>你说的这些框架在面试中完全无人在意，或者说根本不会在意这些框架本身（但是现在大部分的商业级 agent 构建，确实有借鉴最初 langchain 的几大组件）。比如最开始 langchain 最火，你用了，然后 langgraph 又火了，你换不换，autogen 又火了继续换吗？现在 claude / openai 的 SDK 最火 又接着换？那如果后续还有其他框架比这俩 SDK 还火，怎么办呢？</p><p>agent 开发的门槛，并不在你说的框架熟练度和前面那个哥们说的 业务适配什么的。给你分享点我常遇到的问题。</p><p>你能讲讲 transformer 架构吗？ gpt 和 transformer 有啥区别啊？为什么 temperature 会影响输出？<br> RAG 方面，你怎么做的分块？为什么考虑使用这种分块方式？如何优化召回率？使用 rerank 了吗？能说几个比较有新意的 rerank 方法吗？向量数据库怎么选啊？为啥用 milvus ？稀疏向量和稠密向量啥区别啊？ RAG 和微调啥区别啊？你数据集怎么弄的啊？你微调的关键参数都有啥啊？你如何评估微调效果呢？ agent 有什么构建模式吗？输出 token 超出了模型限制怎么办呢？</p><p>好多好多问题呀，我的感觉是基本围绕着四个方向，基础、RAG 、微调、Agent ，一次正经的面试中，这几个方向是一定一定都会被问到的。</p>',11)])])}const _=e(o,[["render",p]]);export{u as __pageData,_ as default};
